  "finishing USB read": ["finissant la lecture de l'USB", "Sluta USB läs", "finitura USB leggere", "USB-lezen afmaken", "terminar leitura USB", "끝내는 USB 읽힌", "完成 USB 讀取", "يُصبحُ يُنهيُ USB يَقْرأُ"],
  "sending USB packet": ["envoi du paquet USB", "Skicka USB-paket", "invio di pacchetti USB", "USB-pakket versturen", "enviando pacote USB", "USB 패킷 전송", "傳送 USB 包", "إرسال حزمة USB"],
